     1	package shop.web;
     2	
     3	import com.fasterxml.jackson.core.JsonProcessingException;
     4	import com.fasterxml.jackson.databind.JsonNode;
     5	import io.javalin.Javalin;
     6	import io.javalin.http.Context;
     7	import java.time.Instant;
     8	import java.util.Map;
     9	import shop.Json;
    10	import shop.domain.DomainException;
    11	import shop.domain.ErrorCode;
    12	import shop.service.Application;
    13	
    14	public final class Routes {
    15	    private Routes() {
    16	    }
    17	
    18	    public static void register(Javalin app, Application services) {
    19	        app.post("/checkout/summary", ctx -> json(ctx, 200,
    20	                services.checkout().summary(CheckoutRequestParser.parse(ctx.body()))));
    21	        app.post("/orders", ctx -> json(ctx, 201,
    22	                services.checkout().register(CheckoutRequestParser.parse(ctx.body()))));
    23	        app.get("/orders/{id}", ctx -> json(ctx, 200, services.orders().get(ctx.pathParam("id"))));
    24	        app.post("/orders/{id}/payment", ctx -> {
    25	            JsonNode body = lenientBody(ctx);
    26	            json(ctx, 200, services.orders().confirmPayment(ctx.pathParam("id"),
    27	                    CheckoutRequestParser.text(body.path("transactionId")), instant(body.path("paidAt"))));
    28	        });
    29	        app.post("/orders/{id}/shipment", ctx -> json(ctx, 200, services.orders().ship(ctx.pathParam("id"),
    30	                CheckoutRequestParser.text(lenientBody(ctx).path("trackingCode")))));
    31	        app.post("/orders/{id}/delivery", ctx -> json(ctx, 200, services.orders().deliver(ctx.pathParam("id"))));
    32	        app.post("/orders/{id}/cancellation", ctx -> json(ctx, 200, services.orders().cancel(ctx.pathParam("id"))));
    33	        app.get("/products/{sku}", ctx -> json(ctx, 200, services.queries().product(ctx.pathParam("sku"))));
    34	        app.get("/customers/{cpf}", ctx -> json(ctx, 200, services.queries().customer(ctx.pathParam("cpf"))));
    35	        app.get("/customers/{cpf}/notifications", ctx -> json(ctx, 200,
    36	                services.queries().notifications(ctx.pathParam("cpf"))));
    37	        app.post("/notifications/{id}/read", ctx -> json(ctx, 200, services.queries().markRead(ctx.pathParam("id"))));
    38	
    39	        app.exception(DomainException.class, (e, ctx) -> json(ctx, e.status(), Map.of("error", e.code().name())));
    40	        app.exception(Exception.class, (e, ctx) -> {
    41	            e.printStackTrace();
    42	            json(ctx, 500, Map.of("error", "INTERNAL_ERROR"));
    43	        });
    44	    }
    45	
    46	    private static void json(Context ctx, int status, Object body) {
    47	        try {
    48	            ctx.status(status).contentType("application/json").result(Json.MAPPER.writeValueAsString(body));
    49	        } catch (JsonProcessingException e) {
    50	            throw new IllegalStateException(e);
    51	        }
    52	    }
    53	
    54	    private static JsonNode lenientBody(Context ctx) {
    55	        try {
    56	            JsonNode node = Json.MAPPER.readTree(ctx.body());
    57	            return node == null ? Json.MAPPER.missingNode() : node;
    58	        } catch (Exception e) {
    59	            return Json.MAPPER.missingNode();
    60	        }
    61	    }
    62	
    63	    private static Instant instant(JsonNode node) {
    64	        try {
    65	            return node.isTextual() ? Instant.parse(node.asText()) : null;
    66	        } catch (Exception e) {
    67	            return null;
    68	        }
    69	    }
    70	}
