     1	package shop.service;
     2	
     3	import java.math.BigDecimal;
     4	import java.util.ArrayList;
     5	import java.util.HashSet;
     6	import java.util.List;
     7	import java.util.Set;
     8	import java.util.regex.Pattern;
     9	import shop.domain.CartLine;
    10	import shop.domain.ClubTier;
    11	import shop.domain.DomainException;
    12	import shop.domain.ErrorCode;
    13	import shop.domain.Money;
    14	import shop.domain.Product;
    15	import shop.domain.Region;
    16	import shop.domain.Summary;
    17	import shop.domain.coupon.Coupon;
    18	import shop.domain.coupon.CouponContext;
    19	import shop.domain.coupon.Coupons;
    20	import shop.domain.payment.PaymentMethod;
    21	import shop.domain.payment.PaymentMethods;
    22	import shop.domain.shipping.ShippingOption;
    23	import shop.domain.shipping.ShippingOptions;
    24	import shop.domain.shipping.ShippingQuote;
    25	import shop.domain.shipping.ShippingRequest;
    26	import shop.persistence.Tx;
    27	
    28	/** Único lugar onde o resumo é calculado: o resumo e o pedido registrado usam o mesmo código. */
    29	public class CheckoutCalculator {
    30	    private static final Pattern ZIP = Pattern.compile("\\d{8}");
    31	
    32	    private final ShippingOptions shippingOptions;
    33	    private final Coupons coupons;
    34	    private final PaymentMethods paymentMethods;
    35	
    36	    public CheckoutCalculator(ShippingOptions shippingOptions, Coupons coupons, PaymentMethods paymentMethods) {
    37	        this.shippingOptions = shippingOptions;
    38	        this.coupons = coupons;
    39	        this.paymentMethods = paymentMethods;
    40	    }
    41	
    42	    /** Valida na ordem definida e devolve o primeiro problema encontrado. */
    43	    public Summary calculate(CheckoutRequest req, Tx tx) {
    44	        List<CartLine> lines = cartLines(req, tx);
    45	        ClubTier tier = ClubTier.parse(req.clubTier());
    46	        Region region = Region.parse(req.region());
    47	        if (req.zipCode() == null || !ZIP.matcher(req.zipCode()).matches()) {
    48	            throw new DomainException(ErrorCode.INVALID_ZIP_CODE);
    49	        }
    50	        ShippingOption shipping = shippingOptions.find(req.shippingMethod())
    51	                .orElseThrow(() -> new DomainException(ErrorCode.INVALID_SHIPPING_METHOD));
    52	
    53	        BigDecimal subtotal = lines.stream().map(CartLine::total).reduce(BigDecimal.ZERO, BigDecimal::add);
    54	        BigDecimal weightKg = lines.stream().map(CartLine::weightKg).reduce(BigDecimal.ZERO, BigDecimal::add);
    55	        ShippingQuote quote = shipping.quote(new ShippingRequest(req.zipCode(), weightKg, region));
    56	        BigDecimal shippingCost = tier.waivesShipping(shipping) ? Money.ZERO : quote.cost();
    57	
    58	        BigDecimal discount = Money.ZERO;
    59	        if (req.coupon() != null) {
    60	            Coupon coupon = coupons.find(req.coupon())
    61	                    .orElseThrow(() -> new DomainException(ErrorCode.INVALID_COUPON));
    62	            boolean firstPurchase = !tx.orders().hasPurchased(req.cpf());
    63	            discount = Coupons.cap(coupon.discount(
    64	                    new CouponContext(lines, subtotal, shippingCost, shipping, firstPurchase)), subtotal);
    65	        }
    66	
    67	        PaymentMethod payment = paymentMethods.find(req.paymentMethod())
    68	                .orElseThrow(() -> new DomainException(ErrorCode.INVALID_PAYMENT_METHOD));
    69	        if (!payment.acceptsInstallments(req.installments())) {
    70	            throw new DomainException(ErrorCode.INVALID_INSTALLMENTS);
    71	        }
    72	        BigDecimal insurance = region.insurance(subtotal);
    73	        BigDecimal orderTotal = subtotal.subtract(discount).add(shippingCost).add(insurance);
    74	        if (!payment.availableFor(orderTotal)) {
    75	            throw new DomainException(ErrorCode.PAYMENT_METHOD_UNAVAILABLE);
    76	        }
    77	        PaymentMethod.PaymentCharge charge = payment.charge(orderTotal, req.installments(), req.coupon() != null);
    78	
    79	        return new Summary(subtotal, discount, shippingCost, quote.days(), insurance,
    80	                charge.finalTotal().subtract(orderTotal), charge.finalTotal(), req.installments(),
    81	                charge.installmentAmount(), tier.credit(subtotal), tier.gift(subtotal));
    82	    }
    83	
    84	    private List<CartLine> cartLines(CheckoutRequest req, Tx tx) {
    85	        if (blank(req.cpf()) || blank(req.email()) || req.items() == null || req.items().isEmpty()) {
    86	            throw new DomainException(ErrorCode.INVALID_ORDER);
    87	        }
    88	        Set<String> seen = new HashSet<>();
    89	        for (CheckoutRequest.RequestItem item : req.items()) {
    90	            if (item == null || blank(item.sku()) || item.quantity() == null || item.quantity() <= 0
    91	                    || !seen.add(item.sku())) {
    92	                throw new DomainException(ErrorCode.INVALID_ORDER);
    93	            }
    94	        }
    95	        List<CartLine> lines = new ArrayList<>();
    96	        for (CheckoutRequest.RequestItem item : req.items()) {
    97	            Product product = tx.products().find(item.sku())
    98	                    .orElseThrow(() -> new DomainException(ErrorCode.UNKNOWN_PRODUCT));
    99	            lines.add(new CartLine(product, item.quantity()));
   100	        }
   101	        if (lines.stream().anyMatch(l -> l.product().discontinued())) {
   102	            throw new DomainException(ErrorCode.PRODUCT_DISCONTINUED);
   103	        }
   104	        if (lines.stream().anyMatch(l -> l.product().stock() < l.quantity())) {
   105	            throw new DomainException(ErrorCode.INSUFFICIENT_STOCK);
   106	        }
   107	        return lines;
   108	    }
   109	
   110	    private static boolean blank(String value) {
   111	        return value == null || value.isBlank();
   112	    }
   113	}
