    13	public class CheckoutService {
    14	    private final Store store;
    15	    private final CheckoutCalculator calculator;
    16	    private final Clock clock;
    17	
    18	    public CheckoutService(Store store, CheckoutCalculator calculator, Clock clock) {
    19	        this.store = store;
    20	        this.calculator = calculator;
    21	        this.clock = clock;
    22	    }
    23	
    24	    public Summary summary(CheckoutRequest request) {
    25	        return store.inTransaction(tx -> calculator.calculate(request, tx));
    26	    }
    27	
    28	    public Order register(CheckoutRequest request) {
    29	        return store.inTransaction(tx -> {
    30	            Summary summary = calculator.calculate(request, tx);
    31	            tx.customers().ensure(request.cpf());
    32	            Order order = new Order(UUID.randomUUID().toString(), OrderStatus.AWAITING_PAYMENT,
    33	                    Instant.now(clock).truncatedTo(ChronoUnit.SECONDS), summary,
    34	                    request.items().stream().map(i -> new CartItem(i.sku(), i.quantity())).toList(), null,
    35	                    request.cpf());
    36	            tx.orders().insert(order);
    37	            return order;
    38	        });
    39	    }
    40	}
