=== service/OrderService.java
     1	package shop.service;
     2	
     3	import java.time.Duration;
     4	import java.time.Instant;
     5	import java.util.List;
     6	import shop.domain.DomainException;
     7	import shop.domain.ErrorCode;
     8	import shop.domain.Order;
     9	import shop.domain.OrderOperation;
    10	import shop.domain.OrderStatus;
    11	import shop.persistence.PaymentRepository;
    12	import shop.persistence.Store;
    13	import shop.persistence.Tx;
    14	
    15	public class OrderService {
    16	    private static final Duration PAYMENT_WINDOW = Duration.ofHours(48);
    17	
    18	    private final Store store;
    19	    private final List<OrderEventListener> listeners;
    20	
    21	    public OrderService(Store store, List<OrderEventListener> listeners) {
    22	        this.store = store;
    23	        this.listeners = listeners;
    24	    }
    25	
    26	    public Order get(String id) {
    27	        return store.inTransaction(tx -> tx.orders().find(id).orElseThrow(OrderService::notFound));
    28	    }
    29	
    30	    private record PaymentOutcome(Order order, ErrorCode error) {
    31	    }
    32	
    33	    /** transactionId e paidAt podem ser nulos (ausentes): a ordem das validações é decidida aqui. */
    34	    public Order confirmPayment(String id, String transactionId, Instant paidAt) {
    35	        PaymentOutcome outcome = store.inTransaction(tx -> {
    36	            Order order = tx.orders().findForUpdate(id).orElseThrow(OrderService::notFound);
    37	            if (transactionId == null || transactionId.isBlank() || paidAt == null) {
    38	                throw new DomainException(ErrorCode.INVALID_ORDER);
    39	            }
    40	            PaymentRepository.PaymentRecord previous = tx.payments().find(id, transactionId).orElse(null);
    41	            if (previous != null) {
    42	                return new PaymentOutcome(order, previous.errorCode() == null ? null
    43	                        : ErrorCode.valueOf(previous.errorCode()));
    44	            }
    45	            OrderOperation.PAY.requireAllowed(order.status());
    46	            if (Duration.between(order.createdAt(), paidAt).compareTo(PAYMENT_WINDOW) > 0) {
    47	                return refuse(tx, order, transactionId, ErrorCode.ORDER_EXPIRED);
    48	            }
    49	            try {
    50	                listeners.forEach(l -> l.onPaid(tx, order));
    51	            } catch (StockShortageException e) {
    52	                return refuse(tx, order, transactionId, ErrorCode.INSUFFICIENT_STOCK);
    53	            }
    54	            Order paid = order.withStatus(OrderOperation.PAY.target());
    55	            tx.orders().update(paid);
    56	            tx.payments().record(id, transactionId, null);
    57	            return new PaymentOutcome(paid, null);
    58	        });
    59	        if (outcome.error() != null) {
    60	            throw DomainException.conflict(outcome.error());
    61	        }
    62	        return outcome.order();
    63	    }
    64	
    65	    private PaymentOutcome refuse(Tx tx, Order order, String transactionId, ErrorCode error) {
    66	        cancelOrder(tx, order, false);
    67	        tx.payments().record(order.id(), transactionId, error.name());
    68	        return new PaymentOutcome(order.withStatus(OrderStatus.CANCELLED), error);
    69	    }
    70	
    71	    public Order ship(String id, String trackingCode) {
    72	        return store.inTransaction(tx -> {
    73	            Order order = tx.orders().findForUpdate(id).orElseThrow(OrderService::notFound);
    74	            if (trackingCode == null || trackingCode.isBlank()) {
    75	                throw new DomainException(ErrorCode.INVALID_ORDER);
    76	            }
    77	            OrderOperation.SHIP.requireAllowed(order.status());
    78	            Order shipped = order.withShipment(OrderOperation.SHIP.target(), trackingCode);
    79	            tx.orders().update(shipped);
    80	            listeners.forEach(l -> l.onShipped(tx, shipped));
    81	            return shipped;
    82	        });
    83	    }
    84	
    85	    public Order deliver(String id) {
    86	        return store.inTransaction(tx -> {
    87	            Order order = tx.orders().findForUpdate(id).orElseThrow(OrderService::notFound);
    88	            OrderOperation.DELIVER.requireAllowed(order.status());
    89	            Order delivered = order.withStatus(OrderOperation.DELIVER.target());
    90	            tx.orders().update(delivered);
    91	            return delivered;
    92	        });
    93	    }
    94	
    95	    public Order cancel(String id) {
    96	        return store.inTransaction(tx -> {
    97	            Order order = tx.orders().findForUpdate(id).orElseThrow(OrderService::notFound);
    98	            OrderOperation.CANCEL.requireAllowed(order.status());
