     1	package shop.web;
     2	
     3	import com.fasterxml.jackson.databind.JsonNode;
     4	import java.util.ArrayList;
     5	import java.util.List;
     6	import shop.Json;
     7	import shop.domain.DomainException;
     8	import shop.domain.ErrorCode;
     9	import shop.service.CheckoutRequest;
    10	
    11	final class CheckoutRequestParser {
    12	    private CheckoutRequestParser() {
    13	    }
    14	
    15	    static CheckoutRequest parse(String body) {
    16	        JsonNode root;
    17	        try {
    18	            root = Json.MAPPER.readTree(body == null ? "" : body);
    19	        } catch (Exception e) {
    20	            throw new DomainException(ErrorCode.INVALID_ORDER);
    21	        }
    22	        if (root == null || !root.isObject()) {
    23	            throw new DomainException(ErrorCode.INVALID_ORDER);
    24	        }
    25	        JsonNode customer = root.path("customer");
    26	        List<CheckoutRequest.RequestItem> items = new ArrayList<>();
    27	        if (root.path("items").isArray()) {
    28	            for (JsonNode item : root.get("items")) {
    29	                JsonNode q = item.path("quantity");
    30	                Integer quantity = q.isIntegralNumber() && q.canConvertToInt() ? q.asInt() : null;
    31	                items.add(new CheckoutRequest.RequestItem(text(item.path("sku")), quantity));
    32	            }
    33	        }
    34	        JsonNode coupon = root.path("coupon");
    35	        JsonNode inst = root.path("installments");
    36	        int installments = inst.isMissingNode() || inst.isNull() ? 1
    37	                : inst.isIntegralNumber() && inst.canConvertToInt() ? inst.asInt() : 0;
    38	        return new CheckoutRequest(text(customer.path("cpf")), text(customer.path("email")), items,
    39	                text(root.path("zipCode")), text(root.path("region")), text(root.path("shippingMethod")),
    40	                coupon.isMissingNode() || coupon.isNull() ? null : coupon.asText(),
    41	                text(root.path("paymentMethod")), installments, text(root.path("clubTier")));
    42	    }
    43	
    44	    static String text(JsonNode node) {
    45	        return node.isTextual() ? node.asText() : null;
    46	    }
    47	}
