540	    19	    @Override
541	    20	    public boolean acceptsInstallments(int installments) {
542	    21	        return installments >= 1 && installments <= MAX_INSTALLMENTS;
543	    22	    }
544	    23	
545	    24	    @Override
546	    25	    public boolean availableFor(BigDecimal orderTotal) {
547	    26	        return true;
548	    27	    }
549	    28	
550	    29	    @Override
551	    30	    public PaymentCharge charge(BigDecimal orderTotal, int installments, boolean couponInformed) {
552	    31	        BigDecimal n = BigDecimal.valueOf(installments);
553	    32	        if (installments <= MAX_INTEREST_FREE) {
