     1	package shop.domain.payment;
     2	
     3	import java.math.BigDecimal;
     4	import java.math.MathContext;
     5	import java.math.RoundingMode;
     6	import shop.domain.Money;
     7	
     8	public class CreditCard implements PaymentMethod {
     9	    private static final int MAX_INSTALLMENTS = 12;
    10	    private static final int MAX_INTEREST_FREE = 3;
    11	    private static final BigDecimal MONTHLY_RATE = new BigDecimal("0.0199");
    12	    private static final MathContext MC = new MathContext(30, RoundingMode.HALF_EVEN);
    13	
    14	    @Override
    15	    public String code() {
    16	        return "CREDIT_CARD";
    17	    }
    18	
    19	    @Override
    20	    public boolean acceptsInstallments(int installments) {
    21	        return installments >= 1 && installments <= MAX_INSTALLMENTS;
    22	    }
    23	
    24	    @Override
    25	    public boolean availableFor(BigDecimal orderTotal) {
    26	        return true;
    27	    }
    28	
    29	    @Override
    30	    public PaymentCharge charge(BigDecimal orderTotal, int installments, boolean couponInformed) {
    31	        BigDecimal n = BigDecimal.valueOf(installments);
    32	        if (installments <= MAX_INTEREST_FREE) {
    33	            return new PaymentCharge(orderTotal, Money.round(orderTotal.divide(n, MC)));
    34	        }
    35	        // Tabela Price: parcela = total * i / (1 - (1 + i)^-n)
    36	        BigDecimal growth = BigDecimal.ONE.add(MONTHLY_RATE).pow(installments);
    37	        BigDecimal denominator = BigDecimal.ONE.subtract(BigDecimal.ONE.divide(growth, MC));
    38	        BigDecimal installment = Money.round(orderTotal.multiply(MONTHLY_RATE).divide(denominator, MC));
    39	        return new PaymentCharge(installment.multiply(n), installment);
    40	    }
