     1	package shop.domain.shipping;
     2	
     3	import com.fasterxml.jackson.databind.JsonNode;
     4	import java.net.URI;
     5	import java.net.http.HttpClient;
     6	import java.net.http.HttpRequest;
     7	import java.net.http.HttpResponse;
     8	import java.time.Duration;
     9	import shop.Json;
    10	
    11	public class TransLogClient implements CarrierClient {
    12	    private static final Duration TIMEOUT = Duration.ofSeconds(2);
    13	
    14	    private final String baseUrl;
    15	    private final HttpClient http = HttpClient.newBuilder().connectTimeout(TIMEOUT).build();
    16	
    17	    public TransLogClient(String baseUrl) {
    18	        this.baseUrl = baseUrl == null ? null : baseUrl.replaceAll("/+$", "");
    19	    }
    20	
    21	    @Override
    22	    public CarrierQuote quote(String zipCode, long weightGrams, String service) {
    23	        if (baseUrl == null || baseUrl.isBlank()) {
    24	            throw new CarrierDownException("TRANSLOG_URL not configured", null);
    25	        }
    26	        JsonNode body;
    27	        try {
    28	            URI uri = URI.create(baseUrl + "/v2/quote?zip=" + zipCode + "&weight_g=" + weightGrams
    29	                    + "&service=" + service);
    30	            HttpRequest request = HttpRequest.newBuilder(uri).timeout(TIMEOUT).GET().build();
    31	            HttpResponse<String> response = http.send(request, HttpResponse.BodyHandlers.ofString());
    32	            if (response.statusCode() != 200) {
    33	                throw new CarrierDownException("TransLog status " + response.statusCode(), null);
    34	            }
    35	            body = Json.MAPPER.readTree(response.body());
    36	        } catch (InterruptedException e) {
    37	            Thread.currentThread().interrupt();
    38	            throw new CarrierDownException("interrupted", e);
    39	        } catch (CarrierDownException e) {
    40	            throw e;
    41	        } catch (Exception e) {
    42	            throw new CarrierDownException("TransLog failure", e);
    43	        }
    44	        if (body != null && body.isObject() && body.has("error")) {
    45	            if ("ZIP_NOT_SERVED".equals(body.get("error").asText())) {
    46	                throw new ZipNotServedException();
    47	            }
    48	            throw new CarrierDownException("TransLog error " + body.get("error"), null);
    49	        }
    50	        if (body == null || !body.path("price_cents").canConvertToLong() || !body.path("price_cents").isIntegralNumber()
    51	                || !body.path("eta_hours").canConvertToInt() || !body.path("eta_hours").isIntegralNumber()
    52	                || body.path("price_cents").asLong() < 0 || body.path("eta_hours").asInt() < 0) {
    53	            throw new CarrierDownException("TransLog unexpected body", null);
    54	        }
    55	        return new CarrierQuote(body.get("price_cents").asLong(), body.get("eta_hours").asInt());
    56	    }
    57	}

